solution:
class Barrier:
    def __init__(self, parties, action=None):
        if type(parties) is not int or parties < 1:
            raise ValueError("Parties must be positive")
        if action is not None and not callable(action):
            raise ValueError("Action must be callable")
        self._parties = parties
        self._action = action
        self._waiting = []
        self._generation = 0
        self._broken = False

    @property
    def waiting(self):
        return list(self._waiting)

    @property
    def generation(self):
        return self._generation

    @property
    def broken(self):
        return self._broken

    def arrive(self, task):
        if self._broken:
            raise ValueError("Barrier is broken")
        if task in self._waiting:
            raise ValueError("Already arrived: " + str(task))
        self._waiting.append(task)
        if len(self._waiting) < self._parties:
            return ("waiting", len(self._waiting))
        if self._action is not None:
            try:
                self._action()
            except Exception:
                self._broken = True
                self._waiting = []
                raise
        released = self._waiting
        self._waiting = []
        self._generation += 1
        return ("released", released)

    def break_barrier(self):
        waiters = self._waiting
        self._waiting = []
        self._broken = True
        return waiters

    def reset(self):
        waiters = self._waiting
        self._waiting = []
        self._broken = False
        self._generation += 1
        return waiters
